// Native Canvas + Web Animations. No remote animation runtime is required.
let dispose=()=>{},paused=false,observer=null,installEvent=null;
try{paused=localStorage.getItem('yash-motion-paused')==='true';}catch{}
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
export function motionPanel(){return `<div class="signal-lab reveal"><div class="lab-top"><span><i></i> SIGNAL LAB</span><span>INTERACTIVE / 001</span></div><div class="lab-tabs" role="group" aria-label="Visualisation mode"><button class="active" data-lab-mode="signal" aria-pressed="true">Signal</button><button data-lab-mode="field" aria-pressed="false">Field</button><button data-lab-mode="lattice" aria-pressed="false">Lattice</button></div><div class="lab-canvas-wrap"><canvas id="signalCanvas" aria-label="Interactive mathematical signal visualisation"></canvas><span class="lab-coordinate">x(t) / visual study</span><span class="lab-coordinate bottom">DRAG TO EXPLORE ↔</span></div><div class="lab-controls"><label for="labFrequency">FREQUENCY <output id="frequencyValue">3.0</output><input id="labFrequency" type="range" min="1" max="8" step="0.1" value="3" aria-label="Visual frequency"></label><label for="labAmplitude">AMPLITUDE <output id="amplitudeValue">0.6</output><input id="labAmplitude" type="range" min="0.1" max="1" step="0.05" value="0.6" aria-label="Visual amplitude"></label></div><div class="lab-bottom"><span>MATHEMATICS → MOTION</span><span id="labState">SINE + HARMONICS</span></div></div>`;}
function updateMotionButton(){document.querySelectorAll('[data-motion-toggle]').forEach(b=>{b.textContent=paused?'▶ Motion off':'Ⅱ Pause motion';b.setAttribute('aria-pressed',String(paused));});document.documentElement.classList.toggle('motion-paused',paused||reduced.matches||document.hidden);}
export function mountMotion(){dispose();observer?.disconnect();updateMotionButton();const animations=[];let raf=0,visible=true,mode='signal',frequency=3,amplitude=.6,phase=0,pointer={x:.5,y:.5},last=0,canvas=document.querySelector('#signalCanvas'),ctx=canvas?.getContext('2d'),w=0,h=0,ro=null,io=null;
 const shouldMove=()=>!paused&&!reduced.matches&&visible&&!document.hidden;
 const start=()=>{updateMotionButton();if(paused||reduced.matches)animations.forEach(a=>a.finish());if(raf)cancelAnimationFrame(raf);raf=0;last=0;if(ctx){draw();if(shouldMove())raf=requestAnimationFrame(tick);}};
 const resize=()=>{if(!canvas)return;const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const d=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);ctx.setTransform(d,0,0,d,0,0);draw();};
 function draw(){if(!ctx||!w||!h)return;ctx.clearRect(0,0,w,h);const dark=ctx.createRadialGradient(w*.5,h*.5,0,w*.5,h*.5,w*.7);dark.addColorStop(0,'#172239');dark.addColorStop(1,'#0c111d');ctx.fillStyle=dark;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#8292b015';ctx.lineWidth=.6;for(let x=20;x<w;x+=24){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let y=15;y<h;y+=24){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}
 const colors=['#64ebff','#b698ff','#ff9a62'];if(mode==='signal'){ctx.strokeStyle='#ffffff22';ctx.beginPath();ctx.moveTo(18,h/2);ctx.lineTo(w-18,h/2);ctx.stroke();colors.forEach((color,k)=>{ctx.beginPath();for(let x=18;x<w-18;x+=2){const p=(x-18)/(w-36),a=amplitude*h*.31/(1+k*.38),f=frequency*(1+k*.5);const y=h*.5+Math.sin(p*Math.PI*2*f-phase*(1+k*.3))*a*(.45+.55*Math.sin(p*Math.PI));x===18?ctx.moveTo(x,y):ctx.lineTo(x,y);}ctx.strokeStyle=color;ctx.lineWidth=k?1.4:2.5;ctx.shadowBlur=k?8:16;ctx.shadowColor=color;ctx.stroke();ctx.shadowBlur=0;});const x=w*(.15+.7*pointer.x),p=(x-18)/(w-36),y=h*.5+Math.sin(p*Math.PI*2*frequency-phase)*amplitude*h*.31*(.45+.55*Math.sin(p*Math.PI));ctx.fillStyle=colors[0];ctx.beginPath();ctx.arc(x,y,4,0,7);ctx.fill();ctx.strokeStyle='#64ebff33';ctx.beginPath();ctx.arc(x,y,15,0,7);ctx.stroke();}
 else if(mode==='field'){const cx=w*.5,cy=h*.5,n=Math.floor(110+frequency*12);for(let i=0;i<n;i++){const t=i/n*Math.PI*2*3.8,r=Math.sqrt(i/n)*Math.min(w,h)*(.23+amplitude*.18),angle=t+phase*.3;const x=cx+Math.cos(angle)*r,y=cy+Math.sin(angle)*r*.68+Math.sin(t*2+phase)*8;ctx.fillStyle=colors[i%3];ctx.globalAlpha=.2+.8*i/n;ctx.beginPath();ctx.arc(x,y,1.5+1.8*i/n,0,7);ctx.fill();}ctx.globalAlpha=1;ctx.strokeStyle='#8fd9ff44';ctx.beginPath();ctx.ellipse(cx,cy,Math.min(w,h)*.41,Math.min(w,h)*.28,0,0,7);ctx.stroke();}
 else {const cols=Math.min(20,Math.floor(w/22)),rows=10,step=Math.min(w/(cols+1),h/(rows+2));for(let i=0;i<cols;i++)for(let j=0;j<rows;j++){const dist=Math.hypot(i-cols*pointer.x,j-rows*pointer.y),q=Math.sin(dist*.7*frequency/3-phase),x=(w-cols*step)/2+i*step,y=(h-rows*step)/2+j*step+q*amplitude*9;ctx.fillStyle=colors[(i+j)%3];ctx.globalAlpha=.25+(q+1)*.35;ctx.fillRect(x-2,y-2,3+(q+1)*2,3+(q+1)*2);}ctx.globalAlpha=1;}}
 function tick(time){raf=0;if(!shouldMove())return;if(last&&time-last<30){raf=requestAnimationFrame(tick);return;}const delta=last?Math.min((time-last)/1000,.08):0;last=time;phase+=delta*.85;draw();raf=requestAnimationFrame(tick);}
 const inputs=e=>{if(e.target.id==='labFrequency'){frequency=Number(e.target.value);document.querySelector('#frequencyValue').textContent=frequency.toFixed(1);draw();}if(e.target.id==='labAmplitude'){amplitude=Number(e.target.value);document.querySelector('#amplitudeValue').textContent=amplitude.toFixed(1);draw();}};
 const click=e=>{const b=e.target.closest('[data-lab-mode]');if(!b)return;mode=b.dataset.labMode;document.querySelectorAll('[data-lab-mode]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active));});document.querySelector('#labState').textContent={signal:'SINE + HARMONICS',field:'PARAMETRIC FIELD',lattice:'RADIAL DISPLACEMENT'}[mode];draw();};
 const move=e=>{const r=canvas.getBoundingClientRect();pointer={x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};if(e.buttons){phase=pointer.x*Math.PI*4;}draw();};
 document.addEventListener('input',inputs);document.addEventListener('click',click);document.addEventListener('visibilitychange',start);document.addEventListener('motionchange',start);
 if(canvas&&ctx){ro=new ResizeObserver(resize);ro.observe(canvas);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerdown',move);io=new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;start();});io.observe(canvas);resize();start();}
 if(!paused&&!reduced.matches&&'IntersectionObserver' in window){observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){const a=entry.target.animate([{opacity:.25,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'cubic-bezier(.2,.7,.2,1)',fill:'none'});animations.push(a);observer.unobserve(entry.target);}}),{threshold:.08});document.querySelectorAll('.project-card,.section-head,.panel,.resume-entry,.signal-lab,.stat,.page-heading').forEach(el=>observer.observe(el));}
 const tilt=e=>{if(paused||reduced.matches||!window.matchMedia('(hover:hover) and (pointer:fine)').matches)return;const card=e.target.closest('.project-card');if(!card)return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.setProperty('--rx',`${-y*4}deg`);card.style.setProperty('--ry',`${x*4}deg`);card.style.setProperty('--px',`${(x+.5)*100}%`);card.style.setProperty('--py',`${(y+.5)*100}%`);};
 const untilt=e=>{const card=e.target.closest('.project-card');if(card&&!card.contains(e.relatedTarget)){card.style.setProperty('--rx','0deg');card.style.setProperty('--ry','0deg');}};
 document.addEventListener('pointermove',tilt);document.addEventListener('pointerout',untilt);
 dispose=()=>{cancelAnimationFrame(raf);ro?.disconnect();io?.disconnect();animations.forEach(a=>a.cancel());document.removeEventListener('input',inputs);document.removeEventListener('click',click);document.removeEventListener('visibilitychange',start);document.removeEventListener('motionchange',start);document.removeEventListener('pointermove',tilt);document.removeEventListener('pointerout',untilt);canvas?.removeEventListener('pointermove',move);canvas?.removeEventListener('pointerdown',move);};}
document.addEventListener('click',async e=>{if(e.target.closest('[data-motion-toggle]')){paused=!paused;try{localStorage.setItem('yash-motion-paused',String(paused));}catch{}updateMotionButton();document.dispatchEvent(new Event('motionchange'));}if(e.target.closest('[data-install]')){if(installEvent){await installEvent.prompt();installEvent=null;}else{window.alert('On Android: open this HTTPS site in Chrome, then use ⋮ → Install app or Add to Home screen. On Windows: use the install icon in Chrome or Edge. Installation does not enable cloud synchronization.');}}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;document.querySelectorAll('[data-install]').forEach(b=>b.classList.add('install-ready'));});
reduced.addEventListener('change',()=>{updateMotionButton();document.dispatchEvent(new Event('motionchange'));});
